import io
from PIL import Image
def png():
    b=io.BytesIO(); Image.new("RGB",(900,500),(200,100,50)).save(b,"PNG"); return b.getvalue()
sql("delete from pages where site in ('corporate','homes') and key in ('home','banner','about')"); sql("delete from site_settings where key in ('phone','email','whatsapp')"); sql("delete from seo_meta where path in ('/about','/sale')")
# ---------- site content: draft vs publish ----------
st,h,html=req("GET","/admin/site-content","TT_EDITOR"); check("editor opens Site content",st==200 and "Corporate: home page" in html)
home=find(html,hidden=("block","corporate:home"))
st,loc_,_=submit("/admin/site-content","TT_EDITOR",home,{"f_hero_title":"EDITED HEADLINE","f_hero_text":"Edited paragraph","intent":"draft"})
check("save draft keeps it private",sql("select (draft->>'hero_title') from pages where site='corporate' and key='home'")=="EDITED HEADLINE" and "EDITED HEADLINE" not in req("GET","/",None,"garnet.test")[2])
st,h,html=req("GET","/admin/site-content","TT_EDITOR"); check("draft badge shown",'Unpublished draft' in html)
home=find(html,hidden=("block","corporate:home"))
submit("/admin/site-content","TT_EDITOR",home,{"intent":"publish"})
page=req("GET","/",None,"garnet.test")[2]; check("publish makes headline live on corporate home","EDITED HEADLINE" in page and "Edited paragraph" in page)
check("editing corporate does not change Homes",("EDITED HEADLINE" not in req("GET","/",None,"homes.garnet.test")[2]))
